def manage_account():
    """Manage a bank account using if/else statements."""

    # Initialize the account balance
    account_balance = 0

    while True:
        # Get user input
        user_input = input("Enter a command (deposit, withdraw, balance, or exit): ").lower()

        if user_input == "exit":
            print("Goodbye!")
            break

        elif user_input == "deposit":
            # Get the amount to deposit
            deposit_amount = float(input("Enter the amount to deposit: $"))

            # Check if the deposit is valid
            if deposit_amount > 0:
                account_balance += deposit_amount
                print(f"Account balance: ${account_balance}")
            else:
                print("Deposit amount must be positive. Please try again.")

        elif user_input == "withdraw":
            # Get the amount to withdraw
            withdraw_amount = float(input("Enter the amount to withdraw: $"))

            # Check if the withdrawal is valid
            if withdraw_amount > 0 and account_balance >= withdraw_amount:
                account_balance -= withdraw_amount
                print(f"Account balance: ${account_balance}")
            else:
                print("Invalid withdrawal amount or insufficient funds. Please try again.")

        elif user_input == "balance":
            print(f"Account balance: ${account_balance}")

        else:
            print("Invalid command. Please try again.")


if __name__ == "__main__":
    manage_account()
```

This program allows users to deposit, withdraw, or check the balance of their bank account. It checks for valid input and ensures that the account balance remains non-negative.
